<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\TemplateVariable\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;

use OpenApi\Attributes as OA;
use Throwable;

use Civi\Lughauth\Features\Document\TemplateVariable\Domain\TemplateVariableRef;
use Civi\Lughauth\Features\Document\TemplateVariable\Application\Usecase\Create\TemplateVariableCreateUsecase;
use Civi\Lughauth\Features\Document\TemplateVariable\Application\Usecase\List\TemplateVariableListUsecase;
use Civi\Lughauth\Features\Document\TemplateVariable\Application\Usecase\Update\TemplateVariableUpdateUsecase;
use Civi\Lughauth\Features\Document\TemplateVariable\Application\Usecase\Delete\TemplateVariableDeleteUsecase;
use Civi\Lughauth\Features\Document\TemplateVariable\Application\Usecase\Retrieve\TemplateVariableRetrieveUsecase;
use Civi\Lughauth\Features\Document\TemplateVariable\Application\Usecase\Enable\TemplateVariableEnableUsecase;
use Civi\Lughauth\Features\Document\TemplateVariable\Application\Usecase\Disable\TemplateVariableDisableUsecase;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TemplateVariableAllowController
{
  use LoggerAwareTrait;
  use TracerAwareTrait;

  public function __construct(
    private readonly TemplateVariableCreateUsecase $createUsecase,
    private readonly TemplateVariableListUsecase $listUsecase,
    private readonly TemplateVariableUpdateUsecase $updateUsecase,
    private readonly TemplateVariableDeleteUsecase $deleteUsecase,
    private readonly TemplateVariableRetrieveUsecase $retrieveUsecase,
    private readonly TemplateVariableEnableUsecase $enableUsecase,
    private readonly TemplateVariableDisableUsecase $disableUsecase,
  ) {
  }
  #[OA\Get(path: "/api/me/acl/document/template-variable", tags: ["Template variable access control"], description:"Allows",
    responses: [
      new OA\Response(response: 200, description: "Ok"),
    ])
  ]
  public function genericAllow(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
  {
    $this->logDebug("Check generic allow for Template variable");
    $span = $this->startSpan("Generic allow for Template variable");
    try {
      $value = [
        'allows' => [
          $this->createUsecase->allowCreate(),
          $this->listUsecase->allowList(),
          $this->updateUsecase->allowUpdate(),
        $this->deleteUsecase->allowDelete(),
        $this->retrieveUsecase->allowRetrieve(),
        $this->enableUsecase->allowEnable(),
        $this->disableUsecase->allowDisable(),
        ],
        'fields' => [
          'noEditables' => $this->updateUsecase->fixedFields(),
          'noVisibles' => $this->retrieveUsecase->hiddenFields()
        ]
      ];
      $encoded = json_encode($value);
      $response->getBody()->write($encoded === false ? '' : $encoded);
      return $response->withStatus(200)
            ->withHeader('Content-Type', 'application/json');
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  #[OA\Get(path: "/api/me/acl/document/template-variable/{uid}", tags: ["Template variable access control"], description:"Allows",
    parameters: [
      new OA\PathParameter(name: "uid", required: true, schema: new OA\Schema(type: "string")),
    ],
    responses: [
      new OA\Response(response: 200, description: "Ok"),
      new OA\Response(response: 404, description: "Not found"),
    ])
  ]
  public function contextualAllow(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
  {
    $this->logDebug("Check specific allow for Template variable");
    $span = $this->startSpan("Specific allow for Template variable");
    try {
      if (!isset($args['uid'])) {
        throw new NotFoundException('-');
      }
      $ref = new TemplateVariableRef( uid: $args['uid'] );
      $value = [
        'allows' => [
          $this->updateUsecase->allowUpdate($ref),
        $this->deleteUsecase->allowDelete($ref),
        $this->retrieveUsecase->allowRetrieve($ref),
        $this->enableUsecase->allowEnable($ref),
        $this->disableUsecase->allowDisable($ref),
        ],
        'fields' => [
          'noEditables' => $this->updateUsecase->fixedFields($ref),
          'noVisibles' => $this->retrieveUsecase->hiddenFields($ref)
        ]
      ];
      $encoded = json_encode($value);
      $response->getBody()->write($encoded === false ? '' : $encoded);
      return $response->withStatus(200)
            ->withHeader('Content-Type', 'application/json');
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
}
